const mount = document.querySelector('#game');
const scene = new THREE.Scene();
scene.background = new THREE.Color('#a9c49a');
scene.fog = new THREE.FogExp2('#a9c49a', 0.0085);
const camera = new THREE.PerspectiveCamera(48, innerWidth / innerHeight, 0.1, 260);
const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.65));
renderer.setSize(innerWidth, innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
mount.appendChild(renderer.domElement);

scene.add(new THREE.HemisphereLight('#e7f2d5', '#405a35', 2.0));
const sun = new THREE.DirectionalLight('#fff0c8', 3.2);
sun.position.set(-35, 70, 28); sun.castShadow = true;
sun.shadow.mapSize.set(1024, 1024);
sun.shadow.camera.left = -80; sun.shadow.camera.right = 80;
sun.shadow.camera.top = 80; sun.shadow.camera.bottom = -80;
sun.shadow.bias = -0.0004;
scene.add(sun);
const fill = new THREE.DirectionalLight('#9cc5bd', 0.75); fill.position.set(45, 28, -45); scene.add(fill);

const WORLD = 86;
const ground = new THREE.Mesh(new THREE.PlaneGeometry(210, 210), new THREE.MeshStandardMaterial({ color: '#678858', roughness: 1 }));
ground.rotation.x = -Math.PI / 2; ground.receiveShadow = true; scene.add(ground);
const clearing = new THREE.Mesh(new THREE.CircleGeometry(24, 64), new THREE.MeshStandardMaterial({ color: '#789666', roughness: 1 }));
clearing.rotation.x = -Math.PI / 2; clearing.position.y = 0.015; scene.add(clearing);

let seed = 16473;
const random = () => { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 4294967296; };
const dummy = new THREE.Object3D();
function makeForest() {
  const trunkGeo = new THREE.CylinderGeometry(.2, .38, 4.3, 6);
  const trunkMat = new THREE.MeshStandardMaterial({ color: '#624832', roughness: 1 });
  const coneGeo = new THREE.ConeGeometry(2.4, 5.2, 7);
  const canopyMats = ['#315b3b','#3b6a43','#47794a'].map(color => new THREE.MeshStandardMaterial({ color, roughness: 1 }));
  const trunks = new THREE.InstancedMesh(trunkGeo, trunkMat, 240);
  const crowns = canopyMats.map(mat => new THREE.InstancedMesh(coneGeo, mat, 240));
  const bushGeo = new THREE.IcosahedronGeometry(1.25, 1);
  const bushMesh = new THREE.InstancedMesh(bushGeo, new THREE.MeshStandardMaterial({ color: '#527847', roughness: 1 }), 130);
  let count = 0, bushCount = 0;
  for (let i=0; i<240; i++) {
    const a = random() * Math.PI * 2;
    const radius = 20 + Math.sqrt(random()) * 66;
    const x = Math.cos(a) * radius, z = Math.sin(a) * radius;
    const s = .72 + random() * .7;
    dummy.position.set(x, 2.15*s, z); dummy.rotation.set(0, random()*Math.PI, 0); dummy.scale.set(s,s,s); dummy.updateMatrix();
    trunks.setMatrixAt(count, dummy.matrix);
    for (let layer=0; layer<3; layer++) {
      dummy.position.set(x, (3.4 + layer*1.48)*s, z);
      dummy.rotation.set(0, random()*Math.PI, 0); dummy.scale.set(s, s*(1.02-layer*.08), s); dummy.updateMatrix();
      crowns[layer].setMatrixAt(count, dummy.matrix);
      const tint = new THREE.Color().setHSL(.31 + random()*.06, .29 + random()*.17, .24 + random()*.11);
      crowns[layer].setColorAt(count, tint);
    }
    count++;
  }
  for (let i=0; i<130; i++) {
    const a=random()*Math.PI*2, r=23+random()*58, s=.6+random()*.7;
    dummy.position.set(Math.cos(a)*r, .65*s, Math.sin(a)*r); dummy.rotation.set(random(),random()*6,random()); dummy.scale.set(s,.65*s,s); dummy.updateMatrix();
    bushMesh.setMatrixAt(bushCount++, dummy.matrix);
  }
  trunks.count=count; crowns.forEach(m=>m.count=count); bushMesh.count=bushCount;
  trunks.castShadow=true; trunks.receiveShadow=true; crowns.forEach(m=>{m.castShadow=true;m.receiveShadow=true;});
  scene.add(trunks, ...crowns, bushMesh);
  // A broken ring of soft, mossy stones marks the edge of the old grove.
  const stoneGeo = new THREE.DodecahedronGeometry(1, 0);
  const stones = new THREE.InstancedMesh(stoneGeo, new THREE.MeshStandardMaterial({ color:'#77836a',roughness:1 }), 48);
  for(let i=0;i<48;i++) { const a=i/48*Math.PI*2, r=75+random()*6, s=.6+random()*1.5; dummy.position.set(Math.cos(a)*r,.55*s,Math.sin(a)*r);dummy.rotation.set(random(),random()*5,random());dummy.scale.set(s*.9,s*.6,s);dummy.updateMatrix();stones.setMatrixAt(i,dummy.matrix); }
  stones.castShadow=true; scene.add(stones);
}
makeForest();
// Tiny firefly-like motes are deliberately sparse, keeping the clearing calm.
const motes = [];
for (let i=0;i<16;i++) { const m=new THREE.Mesh(new THREE.SphereGeometry(.09,8,6),new THREE.MeshBasicMaterial({color:'#d8f6a0'})); m.position.set((random()-.5)*38,.8+random()*3,(random()-.5)*38);scene.add(m);motes.push(m); }

const fruitColors = ['#ffc66d','#ff8e72','#9be9cc','#c9a7ff'];
const fruitGeo = new THREE.SphereGeometry(.44, 14, 12);
const fruitMats = fruitColors.map(c => new THREE.MeshStandardMaterial({ color:c, emissive:c, emissiveIntensity:.55, roughness:.3, metalness:.05 }));
const fruitStemGeo = new THREE.CylinderGeometry(.055,.075,.22,6);
const fruits = [];
function fruitPosition() { const a=random()*Math.PI*2, r=7+random()*63; return new THREE.Vector3(Math.cos(a)*r,.72,Math.sin(a)*r); }
for(let i=0;i<58;i++) {
  const group=new THREE.Group(); const orb=new THREE.Mesh(fruitGeo,fruitMats[i%fruitMats.length]);
  orb.castShadow=true; group.add(orb);
  const stem=new THREE.Mesh(fruitStemGeo,new THREE.MeshStandardMaterial({color:'#557b42',roughness:1})); stem.position.y=.43;group.add(stem);
  const halo=new THREE.Mesh(new THREE.TorusGeometry(.61,.035,6,18),new THREE.MeshBasicMaterial({color:fruitColors[i%fruitColors.length],transparent:true,opacity:.38}));halo.rotation.x=Math.PI/2;halo.position.y=-.12;group.add(halo);
  group.position.copy(fruitPosition()); scene.add(group); fruits.push({group,active:true,phase:random()*6});
}

class Worm {
  constructor(name,color,accent,isPlayer=false) {
    this.name=name;this.color=color;this.accent=accent;this.isPlayer=isPlayer;this.heading=random()*Math.PI*2;this.speed=10;
    this.pos=new THREE.Vector3();this.path=[];this.step=0;this.length=isPlayer?8:7+Math.floor(random()*6);this.score=0;this.alive=true;
    this.root=new THREE.Group();scene.add(this.root);
    const bodyMat=new THREE.MeshStandardMaterial({color,roughness:.36,metalness:.03});
    const stripeMat=new THREE.MeshStandardMaterial({color:accent,roughness:.32,metalness:.03});
    this.segments=[];
    const sphereGeo=new THREE.SphereGeometry(1,16,12);
    for(let i=0;i<68;i++) {
      const mesh=new THREE.Mesh(sphereGeo,i%3===0?stripeMat:bodyMat);mesh.scale.set(.87,.75,1.06);mesh.castShadow=true;mesh.receiveShadow=true;
      this.root.add(mesh);this.segments.push(mesh);
    }
    this.head=new THREE.Group();this.root.add(this.head);
    const headMesh=new THREE.Mesh(new THREE.SphereGeometry(.94,20,16),bodyMat);headMesh.scale.set(1,.83,1.08);headMesh.castShadow=true;this.head.add(headMesh);
    const belly=new THREE.Mesh(new THREE.SphereGeometry(.72,16,12),new THREE.MeshStandardMaterial({color:accent,roughness:.55}));belly.scale.set(.78,.28,.7);belly.position.set(0,-.52,.05);this.head.add(belly);
    const eyeWhite=new THREE.MeshStandardMaterial({color:'#fff8df',roughness:.24});
    const iris=new THREE.MeshStandardMaterial({color:'#263a28',roughness:.2});
    for(const side of [-1,1]) {
      const eye=new THREE.Mesh(new THREE.SphereGeometry(.24,12,10),eyeWhite);eye.position.set(side*.48,.38,.53);this.head.add(eye);
      const pupil=new THREE.Mesh(new THREE.SphereGeometry(.12,10,8),iris);pupil.position.set(side*.49,.39,.72);this.head.add(pupil);
      const shine=new THREE.Mesh(new THREE.SphereGeometry(.045,8,6),new THREE.MeshBasicMaterial({color:'white'}));shine.position.set(side*.52,.44,.81);this.head.add(shine);
    }
    const feelerMat=new THREE.MeshStandardMaterial({color:accent,roughness:.4});
    for(const side of [-1,1]) { const feeler=new THREE.Mesh(new THREE.ConeGeometry(.09,.48,8),feelerMat);feeler.position.set(side*.25,.85,.58);feeler.rotation.x=-.45;this.head.add(feeler); }
    this.reset(isPlayer?0:1);
  }
  reset(bot=0) {
    const angle=bot?random()*Math.PI*2:0, r=bot?14+random()*31:0;
    this.pos.set(Math.cos(angle)*r,.95,Math.sin(angle)*r);
    if(!bot)this.heading=0; else this.heading=angle+Math.PI*.5;
    this.path=[];for(let i=0;i<230;i++)this.path.push(this.pos.clone().add(new THREE.Vector3(0,0,-i*.25)));
    this.step=0;this.root.visible=true;this.alive=true;
    this.sync();
  }
  sync() {
    const dir=new THREE.Vector3(Math.sin(this.heading),0,Math.cos(this.heading));
    this.head.position.set(this.pos.x,this.pos.y,this.pos.z);this.head.rotation.y=this.heading;
    for(let i=0;i<this.segments.length;i++) {
      const p=this.path[Math.min(this.path.length-1,Math.floor((i+1)*1.12/.25))]||this.pos;
      const mesh=this.segments[i];mesh.visible=i<this.length-1;
      mesh.position.set(p.x,p.y-.06,p.z);const wave=1+Math.sin(i*.65+performance.now()*.003)*.035;
      mesh.scale.set(.83*wave,.7*wave,1.02*wave);
    }
  }
  move(dt,turn,boost=false) {
    if(!this.alive)return;
    this.heading+=turn*dt*2.35;
    const speed=this.isPlayer?(boost?15.2:10.4):(8.2+Math.min(this.length*.13,2.4));
    const v= new THREE.Vector3(Math.sin(this.heading),0,Math.cos(this.heading));
    this.pos.addScaledVector(v,speed*dt);
    this.step+=speed*dt;
    while(this.step>=.25){this.step-=.25;this.path.unshift(this.pos.clone());if(this.path.length>260)this.path.pop();}
    this.pos.y=.94+Math.sin(performance.now()*.005+this.heading)*.045;
    this.sync();
  }
}

const player=new Worm('Moss','#57cfa7','#bcf17e',true);
const bots=[
  new Worm('Fern','#ed9b64','#ffe0a2'),new Worm('Pip','#d27fbc','#f8c5e3'),
  new Worm('Juniper','#65a8e8','#b9e8ff'),new Worm('Thistle','#e2c75e','#fff0a0')
];
const allWorms=[player,...bots];

