const allWorms=[player,...bots];
const ui={overlay:document.querySelector('#overlay'),hero:document.querySelector('#hero'),score:document.querySelector('#score'),length:document.querySelector('#length'),growth:document.querySelector('#growth'),leaderboard:document.querySelector('#leaderboard'),toast:document.querySelector('#toast'),name:document.querySelector('#playerName')};
let running=false,paused=false,gameStarted=false,score=0,boostEnergy=1,lastTime=0,toastTimer=0;
let pointerActive=false,pointer={x:innerWidth*.5,y:innerHeight*.44};
const keys=new Set();
const raycaster=new THREE.Raycaster(), groundPlane=new THREE.Plane(new THREE.Vector3(0,1,0),0), pointerWorld=new THREE.Vector3();
const map=document.querySelector('#map'),mapCtx=map.getContext('2d');

function setOverlay(title,eyebrow,copy,button,action,gameover=false) {
  ui.hero.innerHTML=`<div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="hero-copy">${copy}</p>${gameover?`<div class="stat-value" style="margin:20px 0 2px;color:#c8ef83">${score.toLocaleString()} <small>points · ${player.length}m</small></div>`:''}<button class="play-btn" id="dynamicPlay">${button} <span>→</span></button>${gameover?'':`<div class="tips"><span><b>✦</b> Gather glowberries</span><span><b>↗</b> Outgrow the pack</span><span><b>☘</b> Dodge the tails</span></div>`}`;
  ui.overlay.classList.remove('hidden');ui.overlay.classList.toggle('gameover',gameover);
  document.querySelector('#dynamicPlay').addEventListener('click',action);
}
function startGame() {
  score=0;boostEnergy=1;player.length=8;player.score=0;player.reset(0);
  bots.forEach((bot,i)=>{bot.length=7+Math.floor(random()*4);bot.score=20+Math.floor(random()*60);bot.reset(1);bot.pos.set((random()-.5)*46,.94,(random()-.5)*46);bot.path=Array.from({length:230},(_,j)=>bot.pos.clone().add(new THREE.Vector3(0,0,-j*.25)));bot.aiTimer=random()*2;bot.aiTurn=0;});
  fruits.forEach((f,i)=>{f.active=true;f.group.visible=true;f.group.position.copy(fruitPosition());});
  player.name=(ui.name?.value||'Moss').trim().slice(0,14)||'Moss';
  running=true;paused=false;gameStarted=true;ui.overlay.classList.add('hidden');ui.overlay.classList.remove('gameover');
  lastTime=performance.now();updateHUD();
}
document.querySelector('#playBtn').addEventListener('click',startGame);
document.querySelector('#pauseBtn').addEventListener('click',()=>{
  if(!gameStarted)return;
  if(running){running=false;paused=true;setOverlay('TAKE A<br><span>BREATHER.</span>','The forest can wait','Your little serpent is safe. Jump back in whenever you are ready.','Keep exploring',()=>{paused=false;running=true;ui.overlay.classList.add('hidden');lastTime=performance.now();});}
  else if(paused){paused=false;running=true;ui.overlay.classList.add('hidden');lastTime=performance.now();}
});
document.addEventListener('keydown',e=>{
  if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();
  keys.add(e.key.toLowerCase());
  if(e.key==='Escape'&&gameStarted){if(running)document.querySelector('#pauseBtn').click();else if(paused)document.querySelector('#pauseBtn').click();}
});
document.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
renderer.domElement.style.touchAction='none';
renderer.domElement.addEventListener('pointermove',e=>{pointer={x:e.clientX,y:e.clientY};pointerActive=true;});
renderer.domElement.addEventListener('pointerdown',e=>{pointer={x:e.clientX,y:e.clientY};pointerActive=true;});
document.querySelector('#soundBtn').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♫':'♪';e.currentTarget.style.color=soundOn?'#c8ef83':'';if(soundOn)chime(520);});
let soundOn=false,audio;
function chime(freq=700){if(!soundOn)return;try{audio ||= new (window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const osc=audio.createOscillator(),gain=audio.createGain();osc.type='sine';osc.frequency.setValueAtTime(freq,audio.currentTime);osc.frequency.exponentialRampToValueAtTime(freq*1.55,audio.currentTime+.12);gain.gain.setValueAtTime(.055,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.22);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+.23);}catch{}}
function notify(text){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),1250);}

function updateHUD(){
  ui.score.innerHTML=`${String(score).padStart(3,'0')} <small>pts</small>`;
  ui.length.innerHTML=`${String(player.length).padStart(2,'0')} <small>m</small>`;
  ui.growth.style.width=`${Math.min(100,(player.length%10)*10)}%`;
  const sorted=[...bots,player].sort((a,b)=>(b.score+b.length*3)-(a.score+a.length*3));
  ui.leaderboard.innerHTML=sorted.slice(0,5).map((w,i)=>`<div class="rank-row ${w===player?'you':''}"><span class="rank">${String(i+1).padStart(2,'0')}</span><span class="rank-name">${w.name}${w===player?' · you':''}</span><span class="rank-score">${w.score+w.length*3}</span></div>`).join('');
}
function updateMap(){
  const w=map.width,h=map.height,cx=w/2,cy=h/2,scale=w/(WORLD*2.15);
  mapCtx.clearRect(0,0,w,h);mapCtx.fillStyle='#192e22';mapCtx.fillRect(0,0,w,h);
  mapCtx.strokeStyle='#a7c58c35';mapCtx.lineWidth=2;mapCtx.beginPath();mapCtx.arc(cx,cy,WORLD*scale,0,Math.PI*2);mapCtx.stroke();
  mapCtx.fillStyle='#809e6638';mapCtx.beginPath();mapCtx.arc(cx,cy,24*scale,0,Math.PI*2);mapCtx.fill();
  fruits.forEach(f=>{if(f.active){mapCtx.fillStyle='#f8c46b';mapCtx.fillRect(cx+f.group.position.x*scale-1,cy+f.group.position.z*scale-1,2.4,2.4);}});
  for(const worm of allWorms){if(!worm.alive)continue;mapCtx.fillStyle=worm.isPlayer?'#d9f88d':worm.color;mapCtx.beginPath();mapCtx.arc(cx+worm.pos.x*scale,cy+worm.pos.z*scale,worm.isPlayer?4.7:3.3,0,Math.PI*2);mapCtx.fill();}
}

function changeLength(w,amount){w.length=Math.max(6,Math.min(64,w.length+amount));}
function eatFruit(w,fruit){
  fruit.active=false;fruit.group.visible=false;fruit.group.position.copy(fruitPosition());fruit.group.visible=true;fruit.active=true;
  const points=10+Math.floor(random()*16);w.score+=points;
  if(w.isPlayer){score+=points;changeLength(player,1);boostEnergy=Math.min(1,boostEnergy+.13);chime(620+points*4);notify(`Glowberry +${points} · growing beautifully`);}
  else {changeLength(w,1);}
  updateHUD();
}
function respawnBot(bot){bot.root.visible=false;bot.alive=false;bot.respawnAt=performance.now()+2200;}
function endGame(reason){if(!running)return;running=false;player.alive=false;notify(reason);setTimeout(()=>setOverlay('A WILD<br><span>RUN!</span>','The woods remember you',`${reason} The grove is still glowing. Think you can make it farther next time?`,'Run it back',startGame,true),600);}
function botCollision(bot){respawnBot(bot);for(let n=0;n<3;n++){const f=fruits[n];f.group.position.set(bot.pos.x+(random()-.5)*5,.72,bot.pos.z+(random()-.5)*5);f.active=true;f.group.visible=true;}}

function update(dt,now){
  if(!running)return;
  dt=Math.min(dt,.04);
  const turnLeft=keys.has('a')||keys.has('arrowleft'),turnRight=keys.has('d')||keys.has('arrowright');
  let turn=(turnRight?1:0)-(turnLeft?1:0);
  if(!turn&&pointerActive){
    raycaster.setFromCamera(new THREE.Vector2(pointer.x/innerWidth*2-1,-(pointer.y/innerHeight)*2+1),camera);
    if(raycaster.ray.intersectPlane(groundPlane,pointerWorld)){
      const dx=pointerWorld.x-player.pos.x,dz=pointerWorld.z-player.pos.z;
      if(dx*dx+dz*dz>9){const desired=Math.atan2(dx,dz),diff=Math.atan2(Math.sin(desired-player.heading),Math.cos(desired-player.heading));turn=THREE.MathUtils.clamp(diff*1.35,-1,1);}
    }
  }
  const boostKey=keys.has('shift')||keys.has(' ');
  const boosted=boostKey&&boostEnergy>0;
  if(boosted)boostEnergy=Math.max(0,boostEnergy-dt*.3);else boostEnergy=Math.min(1,boostEnergy+dt*.11);
  if(keys.has('w')||keys.has('arrowup'))player.speed=12.3;else if(keys.has('s')||keys.has('arrowdown'))player.speed=8;else player.speed=10.4;
  player.move(dt,turn,boosted);
  if(Math.hypot(player.pos.x,player.pos.z)>WORLD-1){endGame('You wandered beyond the old forest stones.');return;}
  for(const mote of motes){mote.position.y=1.5+Math.sin(now*.0015+mote.position.x)*1.25;}
  fruits.forEach((f,i)=>{f.group.position.y=.69+Math.sin(now*.002+f.phase)*.12;f.group.rotation.y+=dt*.45;if(player.pos.distanceToSquared(f.group.position)<2.05)eatFruit(player,f);});
  bots.forEach((bot,bi)=>{
    if(!bot.alive){if(now>bot.respawnAt){bot.reset(1);bot.pos.set((random()-.5)*55,.94,(random()-.5)*55);bot.path=Array.from({length:230},(_,j)=>bot.pos.clone().add(new THREE.Vector3(0,0,-j*.25)));bot.score=Math.max(15,bot.score-18);bot.root.visible=true;bot.alive=true;}return;}
    bot.aiTimer-=dt;
    let steering=0;
    if(bot.aiTimer<=0){bot.aiTimer=.6+random()*1.7;bot.aiTurn=(random()-.5)*1.8;}
    steering=bot.aiTurn;
    const radius=Math.hypot(bot.pos.x,bot.pos.z);
    if(radius>64){const toward=Math.atan2(-bot.pos.x,-bot.pos.z);const delta=Math.atan2(Math.sin(toward-bot.heading),Math.cos(toward-bot.heading));steering=THREE.MathUtils.clamp(delta*2,-1,1);}
    // Drift toward nearby snacks, but keep the motion pleasantly imperfect.
    let closest=null,dist=1000;for(const f of fruits){if(!f.active)continue;const d=bot.pos.distanceToSquared(f.group.position);if(d<dist){dist=d;closest=f;}}
    if(closest&&dist<180){const a=Math.atan2(closest.group.position.x-bot.pos.x,closest.group.position.z-bot.pos.z);const d=Math.atan2(Math.sin(a-bot.heading),Math.cos(a-bot.heading));steering=THREE.MathUtils.clamp(d*1.8,-1,1);}
    bot.move(dt,steering,false);
    for(const f of fruits)if(f.active&&bot.pos.distanceToSquared(f.group.position)<1.9){f.group.position.copy(fruitPosition());bot.score+=12;changeLength(bot,1);break;}
    if(player.alive&&bot.pos.distanceToSquared(player.pos)<2.1){if(bot.length>player.length+2){endGame(`${bot.name} was a little too close for comfort.`);return;}else botCollision(bot);}
  });
  // A serpent's head cannot cross another serpent's body.
  for(const bot of bots){if(!bot.alive)continue;for(let i=3;i<bot.length-1;i++){const p=bot.path[Math.floor((i+1)*1.12/.25)];if(p&&player.pos.distanceToSquared(p)<1.65){endGame(`${bot.name}'s tail crossed your path.`);return;}}}
  for(const bot of bots){if(!bot.alive)continue;for(const other of allWorms){if(other===bot||!other.alive)continue;for(let i=3;i<other.length-1;i++){const p=other.path[Math.floor((i+1)*1.12/.25)];if(p&&bot.pos.distanceToSquared(p)<1.5){botCollision(bot);break;}}if(!bot.alive)break;}}
  updateHUD();
}

function animate(now=0){requestAnimationFrame(animate);const dt=lastTime?(now-lastTime)/1000:0;lastTime=now;
  if(running)update(dt,now);
  const dir=new THREE.Vector3(Math.sin(player.heading),0,Math.cos(player.heading));
  const target=new THREE.Vector3(player.pos.x+dir.x*5,player.pos.y,player.pos.z+dir.z*5);
  const desiredCamera=new THREE.Vector3(player.pos.x-dir.x*21,player.pos.y+26,player.pos.z-dir.z*21);
  camera.position.lerp(desiredCamera,1-Math.exp(-dt*3.2));camera.lookAt(target);
  fruits.forEach((f,i)=>{if(f.active){const orb=f.group.children[0];orb.scale.setScalar(1+Math.sin(now*.004+f.phase)*.08);}});
  if(Math.floor(now/500)!==Math.floor((now-dt*1000)/500))updateMap();
  renderer.render(scene,camera);
}
requestAnimationFrame(animate);
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.65));});

